<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
$error=null;$success=null;$users=[];
try{
    $pdo=business_db();security_step17_ensure($pdo);$actor=security_step17_current_user($pdo);$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
        if($action==='create'){$p=(string)($_POST['temporary_password']??'');if(!hash_equals($p,(string)($_POST['confirm_password']??'')))throw new RuntimeException('Temporary password confirmation does not match.');$id=security_step17_create_user($pdo,(string)($_POST['full_name']??''),(string)($_POST['email']??''),(string)($_POST['mobile']??''),(string)($_POST['role_code']??'staff'),$p);$success='User #'.$id.' created. They must change the temporary password at first sign-in.';}
        elseif($action==='update'){$id=(int)($_POST['user_id']??0);security_step17_update_user($pdo,$id,(string)($_POST['full_name']??''),(string)($_POST['mobile']??''),(string)($_POST['role_code']??'staff'),!empty($_POST['is_active']));$success='User #'.$id.' access updated. Affected active sessions were revoked.';}
        elseif($action==='reset'){$id=(int)($_POST['user_id']??0);$p=(string)($_POST['temporary_password']??'');if(!hash_equals($p,(string)($_POST['confirm_password']??'')))throw new RuntimeException('Temporary password confirmation does not match.');security_step17_admin_reset_password($pdo,$id,$p);$success='Password reset for User #'.$id.'. All sessions were revoked and password change is required at next sign-in.';}
    }
    $users=security_step17_users($pdo,$orgId);
}catch(Throwable $e){$error=$e->getMessage();$csrf=$csrf??'';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>User Management - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/step10.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="security_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 17 • User Management</small></span></a><div class="os-top-actions"><a class="os-btn" href="permission_matrix.php">Permissions</a><a class="os-btn" href="security_sessions.php">Sessions</a><a class="os-btn primary" href="security_center.php">Security</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Security</div><nav class="os-nav"><a href="security_center.php"><i class="dot"></i>Security Center</a><a class="active" href="user_management.php"><i class="dot"></i>Users</a><a href="permission_matrix.php"><i class="dot"></i>Permissions</a><a href="security_sessions.php"><i class="dot"></i>Sessions</a><a href="security_audit.php"><i class="dot"></i>Audit</a></nav><div class="os-sidebar-status"><b>Identity rule</b><span>Email is the login ID. Roles control module access; no shared password account is created.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">USERS • ROLES • ACCESS</div><h1>Manage Business OS users without sharing administrator credentials.</h1><p>New users receive an explicitly entered temporary password and are forced to change it. The last active Administrator cannot be disabled or demoted.</p></section><?php if($error):?><div class="pp-alert bad"><strong>User management:</strong> <?= security_step17_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= security_step17_h($success) ?></div><?php endif;?><section class="pp-grid"><article class="os-card pp-span-5"><h2>Create User</h2><form method="post" class="pp-form" autocomplete="off"><input type="hidden" name="csrf" value="<?= security_step17_h($csrf) ?>"><input type="hidden" name="action" value="create"><label>Full Name<input name="full_name" required maxlength="150"></label><label>Email / Login ID<input type="email" name="email" required maxlength="190"></label><label>Mobile<input name="mobile" maxlength="30"></label><label>Role<select name="role_code"><option value="staff">Staff</option><option value="manager">Manager</option><option value="viewer">Viewer</option><option value="admin">Administrator</option></select></label><label>Temporary Password<input type="password" name="temporary_password" required autocomplete="new-password"></label><label>Confirm Password<input type="password" name="confirm_password" required autocomplete="new-password"></label><div class="pp-alert"><strong>Minimum:</strong> 12 characters with uppercase, lowercase, number and special character.</div><button>Create User</button></form></article><article class="os-card pp-span-7"><div class="os-title-row"><div><h2>System Users</h2><p><?= count($users) ?> account(s). Active sessions are shown separately.</p></div><a class="os-btn" href="security_sessions.php">Active Sessions →</a></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last Login</th><th>Sessions</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?= security_step17_h($u['full_name']) ?></b><small><?= security_step17_h($u['email']) ?><?= $u['mobile']?' • '.security_step17_h($u['mobile']):'' ?></small></td><td><span class="pp-badge"><?= security_step17_h(strtoupper((string)$u['role_code'])) ?></span></td><td><?= (int)$u['is_active']===1?'ACTIVE':'INACTIVE' ?><?= (int)$u['must_change_password']===1?'<small>Password change required</small>':'' ?></td><td><?= security_step17_h($u['last_login_at']?:'Never') ?></td><td><?= (int)$u['active_sessions'] ?></td><td><details><summary>Manage</summary><form method="post" class="pp-form" style="min-width:260px"><input type="hidden" name="csrf" value="<?= security_step17_h($csrf) ?>"><input type="hidden" name="action" value="update"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><label>Name<input name="full_name" value="<?= security_step17_h($u['full_name']) ?>" required></label><label>Mobile<input name="mobile" value="<?= security_step17_h($u['mobile']??'') ?>"></label><label>Role<select name="role_code"><?php foreach(['admin'=>'Administrator','manager'=>'Manager','staff'=>'Staff','viewer'=>'Viewer'] as $k=>$v):?><option value="<?= $k ?>" <?= $u['role_code']===$k?'selected':'' ?>><?= $v ?></option><?php endforeach;?></select></label><label><input type="checkbox" name="is_active" value="1" <?= (int)$u['is_active']===1?'checked':'' ?>> Active account</label><button>Save Access</button></form><hr><form method="post" class="pp-form" autocomplete="off"><input type="hidden" name="csrf" value="<?= security_step17_h($csrf) ?>"><input type="hidden" name="action" value="reset"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><label>New Temporary Password<input type="password" name="temporary_password" required autocomplete="new-password"></label><label>Confirm<input type="password" name="confirm_password" required autocomplete="new-password"></label><button>Reset Password & Revoke Sessions</button></form></details></td></tr><?php endforeach;?><?php if(!$users):?><tr><td colspan="6">No system users found.</td></tr><?php endif;?></tbody></table></div></article></section><div class="os-footer-note"><strong>Role defaults:</strong> Manager has operational management + Finance view; Staff has day-to-day operational access; Viewer is read-only. Administrator can customize non-admin roles in Permission Matrix.</div></main></div></body></html>